const response = $input.first().json;
const leads = response.result || [];

if (!Array.isArray(leads) || leads.length === 0) {
  return [{ json: { stalled_count: 0, leads: [], message: 'No stalled leads found.' } }];
}

const now = new Date();
const stalledLeads = leads.map(lead => {
  const lastUpdate = new Date(lead.write_date);
  const hoursStalled = Math.floor((now - lastUpdate) / (1000 * 60 * 60));
  const reminderCount = lead.galacs_reminder_count || 0;
  return {
    id: lead.id,
    name: lead.name || lead.partner_name || 'Lead #' + lead.id,
    agent_id: Array.isArray(lead.user_id) ? lead.user_id[0] : lead.user_id,
    agent_name: Array.isArray(lead.user_id) ? lead.user_id[1] : 'Unknown Agent',
    stage_pipeline: lead.stage_pipeline,
    hours_stalled: hoursStalled,
    reminder_count: reminderCount,
    escalate: reminderCount >= 3
  };
});

return stalledLeads.map(l => ({ json: l }));

